item.description:
 &lt;h3 id=&#34;Overview&#34;&gt;&lt;a href=&#34;#Overview&#34; class=&#34;headerlink&#34; title=&#34;Overview&#34;&gt;&lt;/a&gt;Overview&lt;/h3&gt;&lt;p&gt;In computer science, a topological sort or topological ordering of a &lt;strong&gt;directed graph&lt;/strong&gt; is a linear ordering of its vertices. For instance, the vertices of the graph may represent tasks to be performed, and the edges may represent constraints that one task ust be performed before another; in this application, a topological ordering is just a valid sequence for the tasks.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;A topological ordering is possible if and only if the grapg has no directed cycles&lt;/strong&gt;,that is, if it is a directed acyclic graph (DAG).&lt;/p&gt;
&lt;h3 id=&#34;Example&#34;&gt;&lt;a href=&#34;#Example&#34; class=&#34;headerlink&#34; title=&#34;Example&#34;&gt;&lt;/a&gt;Example&lt;/h3&gt;&lt;p&gt;&lt;img src=&#34;https://hackmd.io/_uploads/HJTxqmVjR.png&#34; alt=&#34;image&#34;&gt;&lt;/p&gt;
&lt;p&gt;This graph has many valid topological sorts, including:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;5,7,3,11,8,2,9,10&lt;/li&gt;
&lt;li&gt;3,5,7,8,11,2,9,10&lt;/li&gt;
&lt;li&gt;3,5,7,8,11,2,10,9&lt;/li&gt;
&lt;li&gt;5,7,3,8,11,2,10,9&lt;/li&gt;
&lt;li&gt;7,5,11,3,10,8,9,2&lt;/li&gt;
&lt;li&gt;5,7,11,2,3,8,9,10&lt;/li&gt;
&lt;li&gt;3,7,8,5,11,10,2,9&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;Algorithms&#34;&gt;&lt;a href=&#34;#Algorithms&#34; class=&#34;headerlink&#34; title=&#34;Algorithms&#34;&gt;&lt;/a&gt;Algorithms&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;Kahn’s algorithm&lt;/strong&gt; &lt;/p&gt;
&lt;p&gt;Time complexity &lt;em&gt;O(V+E)&lt;/em&gt;, Space &lt;em&gt;O(V)&lt;/em&gt;&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;convert input data to a directed graph.&lt;/li&gt;
&lt;li&gt;use an array to record the incoming edges of  vertices.&lt;/li&gt;
&lt;li&gt;add the nodes which has no incoming edge into a queue.&lt;/li&gt;
&lt;li&gt;use the queue to traverse the graph.&lt;/li&gt;
&lt;li&gt;repeat 3 and 4 tile the queue is empty.&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;&lt;strong&gt;DFS&lt;/strong&gt; &lt;/p&gt;
&lt;p&gt;Time complexity &lt;em&gt;O(V+E)&lt;/em&gt;, Space &lt;em&gt;O(V+E)&lt;/em&gt;&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;convert input data to a directed graph.&lt;/li&gt;
&lt;li&gt;use an array to mark vertices’s states, each vertex has three states including initial, temporary and permanent. If we visite a temporary vertex then return false(cycle detect ), if we visite a permanent vertex, then return true. (to avoid repeated traversal) &lt;/li&gt;
&lt;li&gt;add a permanent vertex into the top of a stack.&lt;/li&gt;
&lt;li&gt;repeat 3 and 4 tile all vertices was visited.&lt;/li&gt;
&lt;/ol&gt;
&lt;h3 id=&#34;Problems&#34;&gt;&lt;a href=&#34;#Problems&#34; class=&#34;headerlink&#34; title=&#34;Problems&#34;&gt;&lt;/a&gt;Problems&lt;/h3&gt;&lt;p&gt;&lt;a href=&#34;https://leetcode.com/problems/course-schedule/description/?envType=study-plan-v2&amp;envId=top-interview-150&#34;&gt;Course Schedule&lt;/a&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;cpp&#34;&gt;//Kahn&amp;#39;s algorithm
class Solution &amp;#123;
public:
    bool canFinish(int numCourses, vector&amp;lt;vector&amp;lt;int&amp;gt;&amp;gt;&amp;amp; prerequisites) &amp;#123;
        vector&amp;lt;int&amp;gt;adj[numCourses];
        vector&amp;lt;int&amp;gt;indegree(numCourses,0);
        int ans=0;
        for(auto x:prerequisites)&amp;#123;
            adj[x[1]].push_back(x[0]); //construct a graph (step 1)
            indegree[x[0]]++; //step2
        &amp;#125;
        queue&amp;lt;int&amp;gt;q;
        for(int i=0;i&amp;lt;numCourses;i++)&amp;#123;
            if(indegree[i]==0) q.push(i); //step 3
        &amp;#125;
        while(!q.empty())&amp;#123;
            int now=q.front();
            ans++;
            q.pop();
            for(auto x:adj[now])&amp;#123;
                indegree[x]--;
                if(indegree[x]==0) q.push(x);
            &amp;#125;
        &amp;#125;
        return ans==numCourses;
    &amp;#125;
&amp;#125;;
&lt;/code&gt;&lt;/pre&gt;
&lt;pre&gt;&lt;code class=&#34;cpp&#34;&gt;//DFS
class Solution &amp;#123;
public:
    bool canFinish(int numCourses, vector&amp;lt;vector&amp;lt;int&amp;gt;&amp;gt;&amp;amp; prerequisites) &amp;#123;
        vector&amp;lt;vector&amp;lt;int&amp;gt;&amp;gt;adj(numCourses);
        vector&amp;lt;int&amp;gt;mark(numCourses,0);
        bool rst;
        int ans=0;
        for(auto x:prerequisites)&amp;#123;
            adj[x[1]].push_back(x[0]);
        &amp;#125;
        //mark[i]=0 initial
        //mark[i]=1 temporary
        //mark[i]=2 permanent
        for(int i=0;i&amp;lt;numCourses;i++)&amp;#123;
            if(mark[i]&amp;lt;2)&amp;#123;
                rst=dfs(i,mark,adj);
                if(!rst) return false;
            &amp;#125;
        &amp;#125;
        return true;
    &amp;#125;
    bool dfs(int i,vector&amp;lt;int&amp;gt;&amp;amp;mark,vector&amp;lt;vector&amp;lt;int&amp;gt;&amp;gt;&amp;amp;adj)&amp;#123;
        if(mark[i]==2) return true;
        if(mark[i]==1) return false; //detect cycle
        mark[i]=1;
        for(auto x:adj[i])&amp;#123;
            if(!dfs(x,mark,adj)) return false;
        &amp;#125;
        mark[i]=2;
        return true;
    &amp;#125;
&amp;#125;;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;a href=&#34;https://leetcode.com/problems/course-schedule-ii/description/?envType=study-plan-v2&amp;envId=top-interview-150&#34;&gt;Course Schedule II&lt;/a&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;cpp&#34;&gt;//Kahn&amp;#39;s algorithm
class Solution &amp;#123;
public:
    vector&amp;lt;int&amp;gt; findOrder(int numCourses, vector&amp;lt;vector&amp;lt;int&amp;gt;&amp;gt;&amp;amp; prerequisites) &amp;#123;
        vector&amp;lt;int&amp;gt;adj[numCourses];
        vector&amp;lt;int&amp;gt;indegree(numCourses,0);
        vector&amp;lt;int&amp;gt;ans;
        for(auto x:prerequisites)&amp;#123;
            adj[x[1]].push_back(x[0]);
            indegree[x[0]]++;
        &amp;#125;
        queue&amp;lt;int&amp;gt;q;
        for(int i=0;i&amp;lt;numCourses;i++)&amp;#123;
            if(indegree[i]==0) q.push(i);
        &amp;#125;
        while(!q.empty())&amp;#123;
            int now=q.front();
            ans.push_back(now);
            q.pop();
            for(auto x:adj[now])&amp;#123;
                indegree[x]--;
                if(indegree[x]==0) q.push(x);
            &amp;#125;
        &amp;#125;
        if(ans.size()!=numCourses)&amp;#123;
            return &amp;#123;&amp;#125;;
        &amp;#125;
        return ans;
    &amp;#125;
&amp;#125;;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;#96;&lt;br&gt;&lt;a href=&#34;https://leetcode.com/problems/build-a-matrix-with-conditions/description/&#34;&gt;Build a Matrix with Conditions&lt;/a&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;cpp&#34;&gt;class Solution &amp;#123;
public:
    vector&amp;lt;vector&amp;lt;int&amp;gt;&amp;gt; buildMatrix(int k, vector&amp;lt;vector&amp;lt;int&amp;gt;&amp;gt;&amp;amp; rowConditions, vector&amp;lt;vector&amp;lt;int&amp;gt;&amp;gt;&amp;amp; colConditions) &amp;#123;
        vector&amp;lt;vector&amp;lt;int&amp;gt;&amp;gt;rowgraph(k+1),colgraph(k+1);
        for(auto&amp;amp; rc:rowConditions)&amp;#123;
            rowgraph[rc[0]].push_back(rc[1]);
        &amp;#125;
        for(auto&amp;amp; cc:colConditions)&amp;#123;
            colgraph[cc[0]].push_back(cc[1]);
        &amp;#125;
        vector&amp;lt;int&amp;gt; roworder=topoSort(rowgraph,k);
        vector&amp;lt;int&amp;gt; colorder=topoSort(colgraph,k);

        if(roworder.empty()||colorder.empty()) return&amp;#123;&amp;#125;;
        vector&amp;lt;vector&amp;lt;int&amp;gt;&amp;gt;result(k,vector&amp;lt;int&amp;gt;(k,0));
        unordered_map&amp;lt;int,int&amp;gt;rowMap,colMap;
        for(int i=0;i&amp;lt;k;++i)&amp;#123;
        // i represents position, order[i] represents number
            rowMap[roworder[i]]=i;
            colMap[colorder[i]]=i;
        &amp;#125;
        for(int i=1;i&amp;lt;=k;i++)&amp;#123;
        //Map[i] represent i&amp;#39;s position
            result[rowMap[i]][colMap[i]]=i;
        &amp;#125;
        return result;
    &amp;#125;

    //Kahn&amp;#39;s algorithm
    vector&amp;lt;int&amp;gt; topoSort(vector&amp;lt;vector&amp;lt;int&amp;gt;&amp;gt; &amp;amp;graph, int k)&amp;#123;
        vector&amp;lt;int&amp;gt;indegree(k+1,0),order;
        queue&amp;lt;int&amp;gt;q;
        for(int i=1;i&amp;lt;=k;i++)&amp;#123;
            for(int j:graph[i])&amp;#123;
                ++indegree[j];
            &amp;#125;
        &amp;#125;
        for(int i=1;i&amp;lt;=k;i++)&amp;#123;
            if(indegree[i]==0) q.push(i);
        &amp;#125;
        while(!q.empty())&amp;#123;
            int node=q.front();
            q.pop();
            order.push_back(node);
            for(int adj:graph[node])&amp;#123;
                if(--indegree[adj]==0) q.push(adj);
            &amp;#125;
        &amp;#125;
        return order.size()==k? order:vector&amp;lt;int&amp;gt;();
    &amp;#125;
&amp;#125;;
&lt;/code&gt;&lt;/pre&gt;
